class StudentFeed extends StatefulWidget{final User user;const StudentFeed({super.key,required this.user});@override State<StudentFeed> createState()=>_StudentFeedState();}
class _StudentFeedState extends State<StudentFeed>{final text=TextEditingController();List posts=[];bool busy=false;String image='';String poster='',posterTitle='',posterMsg='';
 @override void initState(){super.initState();load();}
 @override void dispose(){text.dispose();super.dispose();}
 Future<void> load()async{try{final r=await Api.get('/posts');final cfg=await Api.get('/config/app-config');final c=Map<String,dynamic>.from(cfg['config']??{});if(mounted)setState(() {posts=List.from(r['posts']??[]);poster='${c['homePosterUrl']??''}';posterTitle='${c['homePosterTitle']??''}';posterMsg='${c['homePosterMessage']??''}';});}catch(_){}} 
 Future<void> pick()async{final x=await ImagePicker().pickImage(source:ImageSource.gallery,imageQuality:80);if(x==null)return;setState(()=>busy=true);try{image=await Api.upload(File(x.path));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}finally{if(mounted)setState(()=>busy=false);}}
 Future<void> add()async{if(text.text.trim().isEmpty&&image.isEmpty)return;setState(()=>busy=true);try{await Api.post('/posts',{'text':text.text.trim(),'imageUrl':image});text.clear();image='';await load();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}finally{if(mounted)setState(()=>busy=false);}}
