 @override Widget build(BuildContext c)=>RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(16),children:[
  sectionTitle('What’s happening?','Share updates, posters and campus moments.'),
  if(poster.isNotEmpty) Card(clipBehavior:Clip.antiAlias,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(24)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Image.network(poster,height:180,width:double.infinity,fit:BoxFit.cover),Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[if(posterTitle.isNotEmpty)Text(posterTitle,style:const TextStyle(fontSize:20,fontWeight:FontWeight.w900)),if(posterMsg.isNotEmpty)Padding(padding:const EdgeInsets.only(top:4),child:Text(posterMsg))]))])),
  const SizedBox(height:12),
  Card(shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(24)),child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[Row(children:[avatar(widget.user.name,url:widget.user.profilePic),const SizedBox(width:10),const Text('Create a campus post',style:TextStyle(fontWeight:FontWeight.w700))]),const SizedBox(height:12),TextField(controller:text,maxLines:3,decoration:const InputDecoration(hintText:'Tell your campus something...')),if(image.isNotEmpty)Padding(padding:const EdgeInsets.only(top:10),child:ClipRRect(borderRadius:BorderRadius.circular(14),child:Image.network(image,height:150,width:double.infinity,fit:BoxFit.cover))),const SizedBox(height:10),Row(children:[TextButton.icon(onPressed:busy?null:pick,icon:const Icon(Icons.image_outlined),label:const Text('Poster')),const Spacer(),FilledButton.icon(onPressed:busy?null:add,icon:const Icon(Icons.send),label:const Text('Publish'))])]))),
  const SizedBox(height:16),...posts.map((p){final m=Map<String,dynamic>.from(p);final a=m['author'] is Map?m['author']:{};final id='${m['_id']??''}';final mine='${a['_id']??a['id']??''}'==widget.user.id;return Card(margin:const EdgeInsets.only(bottom:12),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(22)),child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
   Row(children:[avatar(a['name'],url:'${a['profilePic']??''}'),const SizedBox(width:10),Expanded(child:Text('${a['name']??'Student'}',style:const TextStyle(fontWeight:FontWeight.w800))),if(mine)IconButton(onPressed:()=>del(id),icon:const Icon(Icons.delete_outline))]),if('${m['text']??''}'.isNotEmpty)Padding(padding:const EdgeInsets.symmetric(vertical:8),child:Text('${m['text']}',style:const TextStyle(fontSize:16))),if('${m['imageUrl']??''}'.isNotEmpty)ClipRRect(borderRadius:BorderRadius.circular(16),child:Image.network('${m['imageUrl']}',height:220,width:double.infinity,fit:BoxFit.cover)),if(m['community'] is Map)Padding(padding:const EdgeInsets.only(top:8),child:Chip(label:Text('${m['community']['name']}'))) ])));})
 ]));}

